      if (this.ias > lim) {
        if (this.time - this.flapMsgT > 3) { this.msg('Закрылки: слишком быстро (≤ ' + Math.round(lim * 3.6) + ' км/ч)'); this.flapMsgT = this.time; }
        return false;
      }
