    if (this.onGround) return this.taxiOps && c.taxiAuto && !this.warnings.size && this.v > 0.5 && !(this.td && !this.td.onDest) ? 4 : 1;
    if (!c.apOn || !c.atOn || this.warnings.size) return 1;
