    if (ev.id === 'engRoll' && kind === 'abort') out = 'ok';
    if (this.diverted && kind === 'ok' && ev.id !== 'runway') out = 'ok';
    if (ev.id === 'runway' && this.gaCount === 0 && kind === 'ok') out = 'fail';
